import React from "react";
import {
  FormItem,
  Input,
  ArrayTable,
  Switch,
  FormButtonGroup,
  Submit,
} from "@storage-fe/formily-arco";
import {
  createForm,
  onFieldChange,
  onFieldReact,
  Field as FieldType
} from "@formily/core";
import {
  ArrayField,
  Field,
  FormProvider,
  ObjectField,
  VoidField,
} from "@formily/react";

const form = createForm({
  effects: () => {
    // 主动联动模式
    onFieldChange("hideFirstColumn", ["value"], (field: FieldType) => {
      field.query("array.column4").take((target) => {
        target.visible = !field.value;
      });
      field.query("array.*.a2").forEach((target) => {
        target.visible = !field.value;
      });
    });
    // 被动联动模式
    onFieldReact("array.*.a2", (field) => {
      field.visible = !field.query(".a1").get("value");
    });
  },
});

export default () => (
  <FormProvider form={form}>
    <Field
      name="hideFirstColumn"
      title="隐藏A2"
      decorator={[FormItem, { labelWidth: "auto" }]}
      component={[Switch]}
    />
    <ArrayField name="array" component={[ArrayTable, {
      mode: "jsx", onRow: (_, i) => {
        return {
          fieldProps: {
            disabled: i === 1,
          },
        }
      }
    }]}>
      <VoidField
        name="column1"
        component={[ArrayTable.Column, {
          title: '测试'
        }]}
      >
        <VoidField name="SortHandle" component={[ArrayTable.SortHandle]} />
      </VoidField>
      <VoidField
        name="column2"
        component={[ArrayTable.Column, { title: "序号" }]}
      >
        <VoidField name="Index" component={[ArrayTable.Index]} />
      </VoidField>
      <VoidField
        name="column3"
        component={[ArrayTable.Column, { title: "显隐 A2" }]}
      >
        <Field name="a1" component={[Switch]} />
      </VoidField>
      <VoidField
        name="column4"
        component={[ArrayTable.Column, { title: { label: 'A2', required: true, } }]}
      >
        <Field name="a2" required component={[Input]} decorator={[FormItem]} />
      </VoidField>
      <VoidField
        name="column5"
        component={[ArrayTable.Column, { title: "A3" }]}
      >
        <Field name="a3" component={[Input]} />
      </VoidField>
      <VoidField
        name="column6"
        component={[ArrayTable.Column, { title: "操作" }]}
      >
        <VoidField name="group" component={[FormItem]}>
          <VoidField name="remove" component={[ArrayTable.Remove]} />
          <VoidField name="oveDown" component={[ArrayTable.MoveDown]} />
          <VoidField name="moveUp" component={[ArrayTable.MoveUp]} />
        </VoidField>
      </VoidField>
      <VoidField
        name="addition"
        component={[ArrayTable.Addition, { title: "添加条目", style: { marginTop: 5 } }]}
      />
    </ArrayField>
    <FormButtonGroup>
      <Submit onSubmit={console.log}>提交</Submit>
    </FormButtonGroup>
  </FormProvider>
);
